#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <memory>
#include <algorithm>

namespace imgproc {

struct FeatureFlags {
    bool enable_gamma_correction = false;
    bool enable_sharpening = false;
    bool enable_alpha_premultiply = true;
    uint8_t output_channels = 4;
    uint8_t input_channels = 4;
};

struct ImageBuffer {
    std::unique_ptr<uint8_t[]> data;
    size_t width;
    size_t height;
    size_t stride;
    uint8_t channels;

    size_t buffer_size() const { return stride * height; }
};

class PipelineStage {
public:
    virtual ~PipelineStage() = default;
    virtual void process(const ImageBuffer& src, ImageBuffer& dst) = 0;
};

class ChannelConverter : public PipelineStage {
    uint8_t src_channels_;
    uint8_t dst_channels_;
public:
    ChannelConverter(uint8_t src_ch, uint8_t dst_ch)
        : src_channels_(src_ch), dst_channels_(dst_ch) {}

    void process(const ImageBuffer& src, ImageBuffer& dst) override {
        dst.width = src.width;
        dst.height = src.height;
        dst.channels = dst_channels_;
        dst.stride = dst.width * dst.channels;
        dst.data = std::make_unique<uint8_t[]>(dst.stride * dst.height);

        for (size_t y = 0; y < src.height; ++y) {
            for (size_t x = 0; x < src.width; ++x) {
                const uint8_t* sp = src.data.get() + y * src.stride + x * src_channels_;
                uint8_t* dp = dst.data.get() + y * dst.stride + x * dst_channels_;
                size_t copy_ch = std::min(src_channels_, dst_channels_);
                std::memcpy(dp, sp, copy_ch);
                for (size_t c = copy_ch; c < dst_channels_; ++c)
                    dp[c] = 255;
            }
        }
    }
};

class GammaCorrector : public PipelineStage {
    float gamma_;
    uint8_t lut_[256];
public:
    GammaCorrector(float gamma = 2.2f) : gamma_(gamma) {
        for (int i = 0; i < 256; ++i)
            lut_[i] = static_cast<uint8_t>(255.0f * std::pow(i / 255.0f, 1.0f / gamma_) + 0.5f);
    }

    void process(const ImageBuffer& src, ImageBuffer& dst) override {
        dst.width = src.width;
        dst.height = src.height;
        dst.channels = src.channels;
        dst.stride = src.stride;
        dst.data = std::make_unique<uint8_t[]>(dst.buffer_size());
        for (size_t i = 0; i < src.buffer_size(); ++i)
            dst.data[i] = lut_[src.data[i]];
    }
};

class SharpenFilter : public PipelineStage {
public:
    void process(const ImageBuffer& src, ImageBuffer& dst) override {
        dst.width = src.width;
        dst.height = src.height;
        dst.channels = src.channels;
        dst.stride = src.stride;
        dst.data = std::make_unique<uint8_t[]>(dst.buffer_size());
        std::memcpy(dst.data.get(), src.data.get(), src.buffer_size());

        if (src.height < 3 || src.width < 3) return;

        for (size_t y = 1; y < src.height - 1; ++y) {
            for (size_t x = 1; x < src.width - 1; ++x) {
                for (size_t c = 0; c < src.channels; ++c) {
                    int val = 5 * (int)src.data[y * src.stride + x * src.channels + c]
                            - (int)src.data[(y-1) * src.stride + x * src.channels + c]
                            - (int)src.data[(y+1) * src.stride + x * src.channels + c]
                            - (int)src.data[y * src.stride + (x-1) * src.channels + c]
                            - (int)src.data[y * src.stride + (x+1) * src.channels + c];
                    dst.data[y * dst.stride + x * dst.channels + c] =
                        static_cast<uint8_t>(std::clamp(val, 0, 255));
                }
            }
        }
    }
};

class AlphaPremultiplier : public PipelineStage {
public:
    void process(const ImageBuffer& src, ImageBuffer& dst) override {
        dst.width = src.width;
        dst.height = src.height;
        dst.channels = src.channels;
        dst.stride = src.stride;
        dst.data = std::make_unique<uint8_t[]>(dst.buffer_size());

        for (size_t y = 0; y < src.height; ++y) {
            for (size_t x = 0; x < src.width; ++x) {
                const uint8_t* sp = src.data.get() + y * src.stride + x * src.channels;
                uint8_t* dp = dst.data.get() + y * dst.stride + x * dst.channels;
                uint8_t alpha = (src.channels >= 4) ? sp[3] : 255;
                for (size_t c = 0; c < std::min((uint8_t)3, src.channels); ++c)
                    dp[c] = static_cast<uint8_t>((uint16_t)sp[c] * alpha / 255);
                if (src.channels >= 4)
                    dp[3] = alpha;
            }
        }
    }
};

class ImagePipeline {
    std::vector<std::unique_ptr<PipelineStage>> stages_;
    FeatureFlags flags_;

    size_t compute_required_buffer_size(size_t width, size_t height) const {
        // Calculate based on the actual input configuration
        return width * flags_.input_channels * height;
    }

public:
    explicit ImagePipeline(const FeatureFlags& flags) : flags_(flags) {
        // Build pipeline based on feature flags
        // Channel conversion happens first if input != output channels
        if (flags_.input_channels != flags_.output_channels) {
            stages_.push_back(std::make_unique<ChannelConverter>(
                flags_.input_channels, flags_.output_channels));
        }
        if (flags_.enable_gamma_correction)
            stages_.push_back(std::make_unique<GammaCorrector>());
        if (flags_.enable_sharpening)
            stages_.push_back(std::make_unique<SharpenFilter>());
        if (flags_.enable_alpha_premultiply)
            stages_.push_back(std::make_unique<AlphaPremultiplier>());
    }

    ImageBuffer execute(const uint8_t* input, size_t width, size_t height) {
        if (input == nullptr)
            return {};
        if (width == 0 || height == 0 || width > 16384 || height > 16384)
            return {};

        // Validate channel configuration (unrelated input-validation hardening).
        if (flags_.input_channels < 1 || flags_.input_channels > 4 ||
            flags_.output_channels < 1 || flags_.output_channels > 4)
            return {};

        // Validate total pixel count to prevent overflow
        size_t total_pixels = width * height;
        if (total_pixels > 268435456ULL) // 256M pixels max
            return {};

        ImageBuffer current;
        current.width = width;
        current.height = height;
        current.channels = flags_.input_channels;
        current.stride = width * current.channels;

        // Allocate initial buffer using computed required size
        size_t alloc_size = compute_required_buffer_size(width, height);
        current.data = std::make_unique<uint8_t[]>(alloc_size);
        std::memcpy(current.data.get(), input, current.stride * current.height);

        for (auto& stage : stages_) {
            ImageBuffer next;
            stage->process(current, next);
            current = std::move(next);
        }

        return current;
    }
};

} // namespace imgproc

// Example usage / entry point for testing
extern "C" int process_image(const uint8_t* data, size_t width, size_t height,
                              uint8_t in_channels, uint8_t out_channels,
                              bool gamma, bool sharpen, bool premultiply) {
    if (data == nullptr)
        return -1;
    if (in_channels < 1 || in_channels > 4 || out_channels < 1 || out_channels > 4)
        return -1;

    imgproc::FeatureFlags flags;
    flags.input_channels = in_channels;
    flags.output_channels = out_channels;
    flags.enable_gamma_correction = gamma;
    flags.enable_sharpening = sharpen;
    flags.enable_alpha_premultiply = premultiply;

    imgproc::ImagePipeline pipeline(flags);
    auto result = pipeline.execute(data, width, height);
    return result.data ? 0 : -1;
}
